/**
 * WHAT EACH NETWORK WORD MEANS — the hover and completion text of the network words (`network-words.ts`). A word that
 * runs answers its row of `network-runs.generated.ts`: a measured state's text and the ST the lowering makes of it, the
 * rows of the "What it runs as" table of `volt-cli/docs/network-text.html` (both generated by
 * `test/package/network-runs.test.ts`). Only the `%LANGUAGE` / `%NETWORK` / `%UNSUPPORTED` lines, which run nothing,
 * say what they are here.
 */
import { NETWORK_RUNS } from "./network-runs.generated.js"

/** The lines that run nothing, keyed by their word. */
const LINE_MEANINGS = {
  LANGUAGE: "the body's language: LD or FBD, written as network text",
  LD: "Ladder Diagram, written as network text",
  FBD: "Function Block Diagram, written as network text",
  NETWORK: "a network starts here; its title is optional",
  UNSUPPORTED: "a network the text cannot spell: kept as the IDE holds it",
} as const

type RunForm = (typeof NETWORK_RUNS)[number]["form"]
export type NetworkForm = keyof typeof LINE_MEANINGS | RunForm

const runOf = (form: RunForm) => NETWORK_RUNS.find((r) => r.form === form)!

const isLine = (form: NetworkForm): form is keyof typeof LINE_MEANINGS => form in LINE_MEANINGS

/** The hover of a network word: a line's meaning, or a form's measured text and the ST it runs as. */
export function networkMeaning(form: NetworkForm): string {
  if (isLine(form)) return LINE_MEANINGS[form]
  const r = runOf(form)
  return `\`\`\`st\n${r.text}\n\`\`\`\nruns as\n\`\`\`st\n${r.runsAs}\n\`\`\``
}

/** The completion detail of a network word: a line's meaning, or the ST its form runs as, on one line. */
export function networkDetail(form: NetworkForm): string {
  return isLine(form) ? LINE_MEANINGS[form] : runOf(form).runsAs.replace(/\s*\n\s*/g, " ")
}

/** A label: the network's own (`l:`) or the one a jump names (`JMP.l`). */
export const labelMeaning = (name: string, jump: boolean): string =>
  jump ? `the label ${name}: where the jump goes` : `the network's label ${name}: a jump's destination`
